function createPreviewCache(budget) {
  const entries = new Map();
  let used = 0;
  return {
    put(key, value, weight) {
      if (entries.has(key)) entries.delete(key);
      entries.set(key, { value, weight });
      used += weight;
      while (used > budget && entries.size > 0) {
        const oldest = entries.keys().next().value;
        used -= entries.get(oldest).weight;
        entries.delete(oldest);
      }
    },
    get(key) { return entries.get(key)?.value; },
    snapshot() { return { keys: [...entries.keys()], used }; }
  };
}
module.exports = { createPreviewCache };

