const test = require('node:test');
const assert = require('node:assert/strict');
const { createPreviewCache } = require('../previews.cjs');
test('replacement releases the old weight', () => {
  const c = createPreviewCache(10);
  c.put('hero','old',6); c.put('hero','new',4);
  assert.deepEqual(c.snapshot(), {keys:['hero'],used:4});
  assert.equal(c.get('hero'), 'new');
  c.put('sidebar','S',6);
  assert.deepEqual(c.snapshot(), {keys:['hero','sidebar'],used:10});
  c.put('hero','large',7);
  assert.deepEqual(c.snapshot(), {keys:['hero'],used:7});
  assert.equal(c.get('sidebar'), undefined);
  assert.equal(c.get('hero'), 'large');
});
test('multiple eviction and repeated equal-weight updates', () => {
  const c = createPreviewCache(10);
  c.put('a','A',3); c.put('b','B',3); c.put('c','C',3);
  c.put('d','D',8);
  assert.deepEqual(c.snapshot(), {keys:['d'],used:8});
  c.put('d','D2',8); c.put('d','D3',8);
  assert.deepEqual(c.snapshot(), {keys:['d'],used:8});
  c.put('e','E',2); c.get('d');
  assert.deepEqual(c.snapshot(), {keys:['d','e'],used:10});
  c.put('d','tiny',1);
  assert.deepEqual(c.snapshot(), {keys:['e','d'],used:3});
  const view = c.snapshot(); view.keys.pop();
  assert.deepEqual(c.snapshot(), {keys:['e','d'],used:3});
});

